function formalModernPaintFirstCode(formalStyle) { return JSON.stringify(Object.fromEntries(Object.keys(PRESENTATION_FORMAL_MODERN_PAINT_IDENTITY).map((key) => [key, formalStyle[key]]))) === JSON.stringify(PRESENTATION_FORMAL_MODERN_PAINT_IDENTITY) ? null : 'presentation_modern_paint_effect_forbidden'; }

function assertAncestorChainEvidence(ancestorChain) {
  assert.equal(ancestorChainEligibilityFirstCode(ancestorChain), null); assert.equal(ancestorChain.valid, true); assert.equal(ancestorChain.firstCode, null); assert.equal(ancestorChain.firstViolation, null); assert.equal(ancestorChain.pseudoFirstViolation, null); assert.equal(ancestorChain.paintViolations.length, 0); assert.equal(ancestorChain.pseudoPaintViolations.length, 0); assert.equal(ancestorChain.ancestorCount, 5); assert.equal(ancestorChain.pseudoRecordCount, 12); assert.equal(ancestorChain.canonicalSha256, sha256(Buffer.from(JSON.stringify(ancestorChain.canonical)))); assert.equal(ancestorChain.pseudoCanonicalSha256, sha256(Buffer.from(JSON.stringify(ancestorChain.pseudoCanonical)))); assert.deepEqual(Object.keys(ancestorChain.expectedPaintIdentity), Object.keys(PRESENTATION_ANCESTOR_PAINT_IDENTITY)); assert.deepEqual(ancestorChain.expectedPaintIdentity, PRESENTATION_ANCESTOR_PAINT_IDENTITY); assert.deepEqual(Object.keys(ancestorChain.expectedPseudoIdentity), Object.keys(PRESENTATION_PSEUDO_COMPOSITOR_IDENTITY)); assert.deepEqual(ancestorChain.expectedPseudoIdentity, PRESENTATION_PSEUDO_COMPOSITOR_IDENTITY); assert.equal(ancestorChain.expectedBlueprint.length, 5);
  const identities = new Set(); for (const [index, entry] of ancestorChain.canonical.entries()) { assert.deepEqual(Object.keys(entry), ['depth', 'nodeIdentity', 'childNodeIdentity', 'tagName', 'namespaceURI', 'id', 'classAttribute', 'childElementIndex', 'parentElementIndex', 'paint']); assert.equal(entry.depth, index); assert.ok(Number.isSafeInteger(entry.nodeIdentity) && entry.nodeIdentity > 0); assert.ok(Number.isSafeInteger(entry.childNodeIdentity) && entry.childNodeIdentity > 0); assert.notEqual(entry.nodeIdentity, entry.childNodeIdentity); assert.equal(entry.childNodeIdentity, index === 0 ? ancestorChain.targetNodeIdentity : ancestorChain.canonical[index - 1].nodeIdentity); assert.ok(Number.isSafeInteger(entry.childElementIndex) && entry.childElementIndex >= 0); assert.equal(entry.parentElementIndex, index === ancestorChain.canonical.length - 1 ? null : ancestorChain.expectedBlueprint[index].parentElementIndex); assert.equal(entry.namespaceURI, 'http://www.w3.org/1999/xhtml'); assert.deepEqual(Object.keys(entry.paint), Object.keys(PRESENTATION_ANCESTOR_PAINT_IDENTITY)); assert.deepEqual(entry.paint, PRESENTATION_ANCESTOR_PAINT_IDENTITY); identities.add(entry.nodeIdentity); } assert.equal(identities.size, ancestorChain.canonical.length);
  for (const [index, entry] of ancestorChain.pseudoCanonical.entries()) { const ownerIndex = Math.floor(index / 2); assert.deepEqual(Object.keys(entry), ['ownerKind', 'ownerDepth', 'ownerNodeIdentity', 'pseudo', 'ownerVisibility', 'paint']); assert.equal(entry.ownerKind, ownerIndex === 0 ? 'formal' : 'ancestor'); assert.equal(entry.ownerDepth, ownerIndex - 1); assert.equal(entry.ownerNodeIdentity, ownerIndex === 0 ? ancestorChain.targetNodeIdentity : ancestorChain.canonical[ownerIndex - 1].nodeIdentity); assert.equal(entry.pseudo, index % 2 === 0 ? '::before' : '::after'); assert.deepEqual(Object.keys(entry.paint), [...Object.keys(PRESENTATION_PSEUDO_COMPOSITOR_IDENTITY), 'visibility']); assert.deepEqual(entry.paint, { ...PRESENTATION_PSEUDO_COMPOSITOR_IDENTITY, visibility: entry.ownerVisibility }); }
}

function assertFitGeometry(snapshot) {
  assert.equal(snapshot.targetCount, 1, 'named evidence target must be unique');
  assert.equal(snapshot.formalCanvasIdentity, true, 'named evidence target must be the formal canvas');
  assert.equal(snapshot.targetMode, 'fit'); assert.equal(snapshot.stageMode, 'fit');
  assert.equal(snapshot.transform, 'none'); assert.equal(snapshot.clipPath, 'none');
  assert.equal(snapshot.objectFit, 'contain');
  assert.deepEqual(snapshot.paintEffects, PRESENTATION_FORMAL_PAINT_IDENTITY, 'formal target CSS paint effect forbidden'); assertAncestorChainEvidence(snapshot.ancestorChain);
  assert.equal(snapshot.overflowAncestors.length, 0, `evidence target has clip-capable ancestors ${JSON.stringify(snapshot.overflowAncestors)}`);
  assert.equal(snapshot.clips.length, 0, `evidence target clipped by ${JSON.stringify(snapshot.clips)}`);
  assert.ok(snapshot.width > 0 && snapshot.height > 0 && snapshot.rect.width > 0 && snapshot.rect.height > 0);
  const crossError = Math.abs(snapshot.rect.width * snapshot.height - snapshot.rect.height * snapshot.width);
  const crossErrorLimit = (snapshot.width + snapshot.height) / 64 + 0.5;
  assert.ok(crossError <= crossErrorLimit, `aspect ratio drift: ${crossError} > ${crossErrorLimit}`);
}

function geometryViolationFirstCode(snapshot) {
  if (snapshot.targetCount !== 1 || snapshot.formalCanvasIdentity !== true) return 'presentation_target_identity_invalid';
  const ancestorIdentityFirstCode = ancestorChainIdentityFirstCode(snapshot.ancestorChain); if (ancestorIdentityFirstCode) return ancestorIdentityFirstCode;
  if (snapshot.targetMode !== 'fit' || snapshot.stageMode !== 'fit') return 'presentation_formal_target_mode_invalid';
  if (snapshot.transform !== 'none') return 'presentation_transform_forbidden';
  if (snapshot.clipPath !== 'none') return 'presentation_clip_path_forbidden';
  if (snapshot.objectFit !== 'contain') return 'presentation_object_fit_invalid';
  if (JSON.stringify(snapshot.paintEffects) !== JSON.stringify(PRESENTATION_FORMAL_PAINT_IDENTITY)) return 'presentation_paint_effect_forbidden';
  const ancestorCompositorFirstCode = ancestorChainCompositorFirstCode(snapshot.ancestorChain); if (ancestorCompositorFirstCode) return ancestorCompositorFirstCode;
  const pseudoFirstCode = pseudoCompositorFirstCode(snapshot.ancestorChain); if (pseudoFirstCode) return pseudoFirstCode;
  if (snapshot.overflowAncestors.length > 0 || snapshot.clips.length > 0) return 'presentation_clipping_ancestor';
  if (!(snapshot.width > 0 && snapshot.height > 0 && snapshot.rect.width > 0 && snapshot.rect.height > 0)) return 'presentation_geometry_invalid';
  const crossError = Math.abs(snapshot.rect.width * snapshot.height - snapshot.rect.height * snapshot.width);
  const crossErrorLimit = (snapshot.width + snapshot.height) / 64 + 0.5;
  if (crossError > crossErrorLimit) return 'presentation_aspect_ratio_invalid';
  return null;
}

async function jump(page, surface, clipId, sourceFrameIndex) {
  if (surface.reveal) {
    await evaluate(page, `(() => { const clip = document.getElementById('revealJumpClip'); const frame = document.getElementById('revealJumpFrame'); clip.value=${JSON.stringify(clipId)}; frame.value=${JSON.stringify(String(sourceFrameIndex))}; document.getElementById('revealJump').click(); return true; })()`);
    await waitFor(page, `document.getElementById('revealDecodeStatus').textContent.includes(${JSON.stringify(`displayed: ${clipId}:${sourceFrameIndex}`)})`, `reveal exact still ${clipId}:${sourceFrameIndex}`, 120_000);
  } else {
    await evaluate(page, `(() => { document.getElementById('jumpClip').value=${JSON.stringify(clipId)}; document.getElementById('jumpFrame').value=${JSON.stringify(String(sourceFrameIndex))}; document.getElementById('jump').click(); return true; })()`);
    await waitFor(page, `document.getElementById('lock').textContent.includes(${JSON.stringify(`sample ${clipId}:${sourceFrameIndex}`)})`, `blind exact still ${clipId}:${sourceFrameIndex}`, 120_000);
  }
}

