  const expectedSourcePath = `/sources/${encodeURIComponent(source.clipId)}.mp4`; const expectedStatus = surface.reveal ? `displayed: ${source.clipId}:${spot.sourceFrameIndex}` : `sample ${source.clipId}:${spot.sourceFrameIndex}`; const videoId = surface.reveal ? 'revealMotion' : 'motion'; const statusId = surface.reveal ? 'revealDecodeStatus' : 'lock';
