  const encoded = await evaluate(page, `(() => { const nodes=[...document.querySelectorAll('[data-sam-goal-evidence-target=${JSON.stringify(surface.target)}]')]; if(nodes.length!==1||!(nodes[0] instanceof HTMLCanvasElement)) return {valid:false,count:nodes.length,tag:nodes[0]?.tagName??null}; const canvas=nodes[0]; return {valid:true,dataUrl:canvas.toDataURL('image/png'),width:canvas.width,height:canvas.height}; })()`);
  if (!encoded.valid) throw Object.assign(new Error('presentation_formal_canvas_identity_missing'), { code: 'presentation_formal_canvas_identity_missing', details: encoded });
  const dimensions = writeBase64Png(outputPath, encoded.dataUrl.slice(encoded.dataUrl.indexOf(',') + 1)); assert.deepEqual(dimensions, { width: encoded.width, height: encoded.height }); return { dimensions };
