    const snapshot = await presentationSnapshot(page, surface); assertFitGeometry(snapshot);
    const key = `${mode}:${viewport.width}x${viewport.height}@${viewport.deviceScaleFactor}:${source.clipId}:${spot.sourceFrameIndex}`;
    const intrinsicFormalPath = path.join(tempDir, `formal-intrinsic-${slug(key)}.png`); const formal = await saveFormalIntrinsic(page, surface, intrinsicFormalPath); assert.deepEqual(formal.dimensions, { width: source.width, height: source.height }); const intrinsicDirectSsim = directExactStillSsim(intrinsicFormalPath, source.sourcePath, spot.sourceFrameIndex); assert.ok(intrinsicDirectSsim >= SSIM_THRESHOLD, `${key}: formal intrinsic direct SSIM ${intrinsicDirectSsim}`);
    await prepareTargetViewport(page, surface); const referenceId = `sam-goal-reference-${slug(key)}`; const reference = await installRealReference(page, surface, source, spot, referenceId); const intrinsicReferencePath = path.join(tempDir, `reference-intrinsic-${slug(key)}.png`); const referenceDimensions = writeBase64Png(intrinsicReferencePath, reference.dataUrl.slice(reference.dataUrl.indexOf(',') + 1)); assert.deepEqual(referenceDimensions, formal.dimensions); const intrinsicReferenceSsim = ssim(intrinsicFormalPath, intrinsicReferencePath, formal.dimensions); assert.ok(intrinsicReferenceSsim >= SSIM_THRESHOLD, `${key}: independent intrinsic SSIM ${intrinsicReferenceSsim}`);
