async function pointerAndInspectionChecks(page, surface, synthetic) {
  const mapping = await evaluate(page, `(() => { const c=document.getElementById(${JSON.stringify(surface.targetId)}); const r=c.getBoundingClientRect(); const f=globalThis.__samGoalPresentationV3.sourcePointFromPointer; return { topLeft:f(c,r.left,r.top), topRight:f(c,r.right,r.top), bottomLeft:f(c,r.left,r.bottom), bottomRight:f(c,r.right,r.bottom), center:f(c,r.left+r.width/2,r.top+r.height/2) }; })()`);
  assert.deepEqual(mapping.topLeft.anchor, { x: 0, y: 0 }); assert.deepEqual(mapping.topRight.anchor, { x: 1, y: 0 }); assert.deepEqual(mapping.bottomLeft.anchor, { x: 0, y: 1 }); assert.deepEqual(mapping.bottomRight.anchor, { x: 1, y: 1 });
  assert.equal(mapping.center.pixelX, Math.floor(synthetic.width / 2)); assert.equal(mapping.center.pixelY, Math.floor(synthetic.height / 2));
  await clickNamedTarget(page, surface.target, { relativeX: 0.5, relativeY: 0.5 });
  if (!surface.reveal) {
    const value = await evaluate(page, `JSON.parse(document.getElementById('value').value)`); assert.ok(Math.abs(value.x - mapping.center.anchor.x) <= 2 / (synthetic.width - 1)); assert.ok(Math.abs(value.y - mapping.center.anchor.y) <= 2 / (synthetic.height - 1));
  }
  await evaluate(page, `document.getElementById(${JSON.stringify(surface.oneToOneId)}).click()`); let snapshot = await presentationSnapshot(page, surface);
  assert.equal(snapshot.targetMode, 'fit', '1:1 inspection replaced formal target'); assert.equal(snapshot.inspectionHidden, false);
  await evaluate(page, `document.getElementById(${JSON.stringify(surface.fitId)}).click()`); snapshot = await presentationSnapshot(page, surface); assertFitGeometry(snapshot); assert.equal(snapshot.inspectionHidden, true);
}

